      "budget_constants": "MAX_WIRE_BYTES 50 KiB, MAX_WIRE_LINES 1600, token estimate = ceil(whole-wire-JSON bytes / 3), MAX_SYMBOLS_PER_FILE 3, MAX_FALLBACK_CANDIDATES 12"
    },
