      "limits": "max_files 8000, max_file_bytes 1 MB, max_total_bytes 32 MB, max_scan_ms 60 s -> RepositoryScanLimitExceeded with 'repository_scan_limit_exceeded: <reason>'; files that vanish or escape the root are skipped during discovery"
    },
    "ranker": "_rank_candidates (PageRank over file nodes with _edge_weight modifiers, plus per-candidate score bonuses), _fallback_candidates (filename-hint mode), _pagerank, _query_terms/_QUERY_CONCEPT_HINTS",
